styles:
/* ═══════════════════════════════════════════════════════════════════
       Home · estética "aurora": mesh gradients multi-hue derivados del
       token --is-accent, profundidad 3D real y cintas en el mismo plano
       que las cards (nunca por encima).
       ═══════════════════════════════════════════════════════════════════ */

    html, body { height: 100%; margin: 0; }
    body { overflow: hidden; }

    /* ── Paleta derivada: 5 hues girados desde --is-accent ─────────────
       Relative color syntax (ya usado en palettes.css) para que la pieza
       sea colorida sin salirse de la marca activa. */
    .home {
      /* Fallback explícito: si falta palettes.css la pieza sigue en color
         en vez de perder todas las declaraciones de marca. */
      --seed: var(--is-accent, #e03131);
      --hue-a: var(--seed);
      --hue-b: oklch(from var(--seed) l c calc(h + 34));
      --hue-c: oklch(from var(--seed) l c calc(h - 36));
      --hue-d: oklch(from var(--seed) calc(l * 1.02) calc(c * 0.95) calc(h - 84));
      --hue-e: oklch(from var(--seed) calc(l * 1.08) c calc(h + 62));

      --glass: color-mix(in srgb, var(--is-bg-elev) 78%, transparent);
      --glass-strong: color-mix(in srgb, var(--is-bg-elev) 92%, transparent);
      --hairline: color-mix(in srgb, var(--is-border) 70%, transparent);

      --shadow-lift:
        0 1px 0 color-mix(in srgb, #fff 7%, transparent) inset,
        0 18px 44px rgb(0 0 0 / 26%),
        0 3px 10px rgb(0 0 0 / 16%);
      --shadow-pop:
        0 1px 0 color-mix(in srgb, #fff 12%, transparent) inset,
        0 34px 72px rgb(0 0 0 / 34%),
        0 6px 18px rgb(0 0 0 / 20%);
    }

    /* ── Lienzo: aurora animada + malla fina + grano ───────────────────── */
    is-main.home-main {
      display: block;
      height: 100%;
      padding: 0;
      overflow: auto;
      position: relative;
      isolation: isolate;
      background: var(--is-bg);
    }

    is-main.home-main::before {
      /* Aurora: 5 blobs de color que respiran lentamente. Caja del tamaño
         exacto del viewport para que los centros en % caigan donde se
         espera; el scale de la animación cubre el sangrado del blur. */
      content: "";
      position: fixed;
      inset: 0;
      z-index: -2;
      pointer-events: none;
      background:
        radial-gradient(48vw 42vh at 4% 2%,   color-mix(in srgb, var(--is-accent, #e03131) 60%, transparent), transparent 66%),
        radial-gradient(44vw 38vh at 92% 8%,  color-mix(in srgb, oklch(from var(--is-accent, #e03131) l c calc(h + 34)) 55%, transparent), transparent 66%),
        radial-gradient(40vw 34vh at 74% 52%, color-mix(in srgb, oklch(from var(--is-accent, #e03131) calc(l * 1.02) calc(c * 0.95) calc(h - 84)) 45%, transparent), transparent 68%),
        radial-gradient(44vw 36vh at 10% 66%, color-mix(in srgb, oklch(from var(--is-accent, #e03131) l c calc(h - 36)) 48%, transparent), transparent 68%),
        radial-gradient(34vw 30vh at 52% 96%, color-mix(in srgb, oklch(from var(--is-accent, #e03131) calc(l * 1.08) c calc(h + 62)) 40%, transparent), transparent 70%);
      filter: blur(72px) saturate(130%);
      opacity: 0.5;
      transform: scale(1.2);
      animation: aurora-breathe 26s ease-in-out infinite alternate;
    }

    /* Sin malla de rejilla sobre el fondo: la textura la aportan las auroras
       del ::before. Una retícula decorativa aquí competía con el contenido y
       es el mismo patrón que ya se retiró de los demos y del playground. */

    @keyframes aurora-breathe {
      0%   { transform: translate3d(0, 0, 0) scale(1.2);          filter: blur(72px) saturate(125%); }
      50%  { transform: translate3d(-2vw, 1.5vh, 0) scale(1.32);  filter: blur(80px) saturate(145%); }
      100% { transform: translate3d(1.5vw, -2vh, 0) scale(1.26);  filter: blur(68px) saturate(135%); }
    }

    /* ── Rejilla de página: hero | stage, luego collage, luego lab ─────
       Antes .home-collage y .home-lab compartían el área "lab": se
       pintaban una encima de la otra. Ahora cada sección tiene su fila. */
    .home {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
      grid-template-areas:
        "hero     stage"
        "showcase showcase";
      gap: clamp(2rem, 5vw, 4.5rem) clamp(1.5rem, 4vw, 3.5rem);
      min-height: 100%;
      padding: clamp(1.75rem, 4.5vw, 4rem) clamp(1.25rem, 4vw, 3.5rem) clamp(3rem, 6vw, 5rem);
      box-sizing: border-box;
    }

    .home-hero     { grid-area: hero; }
    .home-stage    { grid-area: stage; align-self: start; min-width: 0; }
    .home-showcase { grid-area: showcase; min-width: 0; }

    /* ═══════════════ HERO ═══════════════════════════════════════════ */

    .home-hero {
      align-self: start;
      min-width: 0;
      position: relative;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      gap: 1.35rem;
      max-width: min(38rem, 100%);
      padding-top: 0.5rem;
      perspective: 1400px;
      perspective-origin: 30% 25%;
      transform-style: preserve-3d;
      isolation: isolate;
    }

    /* Halo conic girando detrás del titular: da el "épico" sin ruido */
    .home-hero::before {
      content: "";
      position: absolute;
      z-index: -1;
      top: -8rem;
      left: -10rem;
      width: 34rem;
      height: 34rem;
      border-radius: 50%;
      background: conic-gradient(from 0deg,
        color-mix(in srgb, var(--hue-a) 70%, transparent),
        color-mix(in srgb, var(--hue-b) 55%, transparent),
        color-mix(in srgb, var(--hue-d) 50%, transparent),
        color-mix(in srgb, var(--hue-c) 55%, transparent),
        color-mix(in srgb, var(--hue-a) 70%, transparent));
      filter: blur(72px);
      opacity: 0.5;
      pointer-events: none;
      animation: halo-spin 34s linear infinite;
    }

    /* Orbe secundario que deriva: profundidad volumétrica */
    .home-hero::after {
      content: "";
      position: absolute;
      z-index: -1;
      top: 16rem;
      left: 20rem;
      width: 16rem;
      height: 16rem;
      border-radius: 50%;
      background: radial-gradient(circle,
        color-mix(in srgb, var(--hue-d) 60%, transparent) 0%,
        color-mix(in srgb, var(--hue-d) 16%, transparent) 48%,
        transparent 76%);
      filter: blur(46px);
      pointer-events: none;
      animation: orb-drift 17s ease-in-out infinite alternate;
    }

    @keyframes halo-spin { to { transform: rotate(360deg); } }
    @keyframes orb-drift {
      0%   { transform: translate3d(0, 0, 0) scale(1); }
      50%  { transform: translate3d(1.75rem, -1.25rem, 0) scale(1.1); }
      100% { transform: translate3d(-1.25rem, 1.5rem, 0) scale(0.94); }
    }

    /* Kicker como pastilla de cristal con punto vivo */
    .home-kicker {
      margin: 0;
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      padding: 0.34rem 0.85rem 0.34rem 0.6rem;
      border-radius: 999px;
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--is-text);
      background: linear-gradient(135deg,
        color-mix(in srgb, var(--hue-a) 20%, transparent),
        color-mix(in srgb, var(--hue-b) 12%, transparent));
      border: 1px solid color-mix(in srgb, var(--hue-a) 42%, transparent);
      box-shadow:
        0 1px 0 color-mix(in srgb, #fff 10%, transparent) inset,
        0 8px 24px color-mix(in srgb, var(--hue-a) 22%, transparent);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
    }

    .home-kicker::before {
      content: "";
      width: 0.45rem;
      height: 0.45rem;
      border-radius: 50%;
      background: var(--hue-a);
      box-shadow: 0 0 0 0 color-mix(in srgb, var(--hue-a) 60%, transparent);
      animation: kicker-pulse 2.6s ease-out infinite;
    }

    @keyframes kicker-pulse {
      0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--hue-a) 65%, transparent); }
      70%  { box-shadow: 0 0 0 0.6rem color-mix(in srgb, var(--hue-a) 0%, transparent); }
      100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--hue-a) 0%, transparent); }
    }

    /* Titular 3D: capa de relieve + degradado animado + glint */
    .home-title {
      position: relative;
      margin: 0;
      font-size: clamp(2.4rem, 5vw, 4rem);
      font-weight: 800;
      line-height: 1.02;
      letter-spacing: -0.038em;
      color: var(--is-text);
      transform-style: preserve-3d;
      transition: transform 700ms cubic-bezier(.2,.7,.3,1);
      text-shadow:
        0 1px 0 color-mix(in srgb, #fff 6%, transparent),
        0 2px 10px rgb(0 0 0 / 24%),
        0 22px 48px rgb(0 0 0 / 30%);
    }

    .home-title__accent {
      position: relative;
      display: inline-block;
      /* `background-clip: text` solo pinta dentro de la caja del elemento. Con
         el line-height ajustado del titulo, los descendentes (la "p" de
         "rapido") caen por debajo y se quedan SIN degradado. Se agranda la
         caja pintada y se compensa con margin para no mover el layout. */
      padding-block: 0.14em 0.24em;
      margin-block: -0.14em -0.24em;
      background: linear-gradient(115deg,
        var(--hue-a) 0%,
        var(--hue-b) 26%,
        color-mix(in srgb, var(--hue-d) 78%, #fff) 52%,
        var(--hue-c) 76%,
        var(--hue-a) 100%);
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
      color: transparent;
      /* El texto con relleno transparente NO tapa su propia text-shadow: la
         sombra se ve A TRAVES del glifo. `.home-title` hereda en light una
         sombra blanca al 70%, que cubria las letras y las dejaba palidas e
         ilegibles (y comia el degradado del descendente de la "p"). Cualquier
         elemento con background-clip:text debe cancelar la sombra heredada. */
      text-shadow: none;
      /* Sin animar background-position ni filter aquí: Chrome pierde el
         background-clip:text al componer esa combinación. El movimiento
         lo aporta el glint de ::after (transform, sí compositable). */
    }

    /* Sin glint: el barrido pintaba la CAJA del span, no las letras (el
       relleno del texto es transparente), y dejaba un chaflán gris
       flotando al lado del titular. El degradado ya aporta suficiente. */

    .home-hero:hover .home-title { transform: translateZ(26px) rotateX(3deg); }

    .home-lede {
      margin: 0;
      max-width: 33rem;
      font-size: 1.06rem;
      line-height: 1.58;
      color: var(--is-text-soft);
    }

    .home-lede .code {
      color: var(--is-text);
      background: color-mix(in srgb, var(--hue-a) 14%, transparent);
      border: 1px solid color-mix(in srgb, var(--hue-a) 30%, transparent);
      border-radius: 0.35rem;
      padding: 0.05em 0.35em;
    }

    /* Acciones: la CTA principal lleva anillo de luz degradado */
    .home-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem;
      margin-top: 0.3rem;
      transform-style: preserve-3d;
      transition: transform 700ms cubic-bezier(.2,.7,.3,1);
    }

    .home-hero:hover .home-actions { transform: translateZ(34px); }

    .home-actions #ctaExplore {
      position: relative;
      border-radius: 0.6rem;
      box-shadow:
        0 10px 30px color-mix(in srgb, var(--hue-a) 42%, transparent),
        0 2px 6px color-mix(in srgb, var(--hue-a) 30%, transparent);
    }

    .home-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.4rem;
      margin: 0.15rem 0 0;
    }

    .home-meta is-tag { font-size: 0.72rem; }

    /* ── Snippet CDN: borde degradado, cristal ─────────────────────── */
    /* Ventana-editor: chrome con traffic lights + pestaña de archivo, el
       código dentro y un strip "resultado en vivo" como payoff. */
    .home-cdn {
      display: grid;
      gap: 0;
      margin-top: 0.9rem;
      max-width: min(40rem, 100%);
      width: 100%;
      position: relative;
      z-index: 2;
      border-radius: 0.9rem;
      border: 1px solid var(--hairline);
      background: var(--glass-strong);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      box-shadow:
        0 24px 60px rgb(0 0 0 / 32%),
        0 2px 8px rgb(0 0 0 / 18%);
      overflow: hidden;
    }

    .home-cdn__bar {
      display: flex;
      align-items: center;
      gap: 0.7rem;
      padding: 0.55rem 0.85rem;
      border-bottom: 1px solid var(--hairline);
      background: color-mix(in srgb, var(--is-bg-elev) 68%, transparent);
    }

    .home-cdn__dots { display: inline-flex; gap: 6px; }
    .home-cdn__dots i {
      width: 11px;
      height: 11px;
      border-radius: 50%;
      background: #fe5f57;
    }
    .home-cdn__dots i:nth-child(2) { background: #febb2e; }
    .home-cdn__dots i:nth-child(3) { background: #28c840; }

    .home-cdn__file {
      font-family: var(--is-mono, ui-monospace, Consolas, monospace);
      font-size: 0.72rem;
      font-weight: 600;
      color: var(--is-text-soft);
      padding: 0.18rem 0.6rem;
      border-radius: 0.4rem;
      background: color-mix(in srgb, var(--is-bg) 55%, transparent);
      border: 1px solid var(--hairline);
    }

    .home-cdn__tabs {
      display: inline-flex;
      gap: 0.25rem;
      padding: 0.18rem;
      margin-left: auto;
      border-radius: 999px;
      background: color-mix(in srgb, var(--is-bg) 45%, transparent);
      border: 1px solid var(--hairline);
      width: max-content;
    }

    .home-cdn__tab {
      appearance: none;
      border: 0;
      background: transparent;
      color: var(--is-text-soft);
      font: inherit;
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      padding: 0.32rem 0.9rem;
      border-radius: 999px;
      cursor: pointer;
      transition: background 160ms ease, color 160ms ease, box-shadow 160ms ease;
    }

    .home-cdn__tab[aria-pressed="true"] {
      background: linear-gradient(135deg, var(--hue-a), var(--hue-b));
      color: var(--is-on-brand, #fff);
      box-shadow: 0 6px 18px color-mix(in srgb, var(--hue-a) 38%, transparent);
    }

    .home-cdn__panel {
      position: relative;
      padding: 0.75rem 0.95rem 0.85rem;
      min-width: 0;
      max-width: 100%;
      box-sizing: border-box;
    }

    .home-cdn__panel-header {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.5rem;
      margin-bottom: 0.55rem;
    }

    .home-cdn__hint {
      font-size: 0.72rem;
      font-weight: 600;
      color: var(--is-text-soft);
      letter-spacing: 0.02em;
    }

    .home-cdn__copy {
      appearance: none;
      display: inline-flex;
      align-items: center;
      gap: 0.3rem;
      padding: 0.3rem 0.7rem;
      border-radius: 999px;
      border: 1px solid var(--hairline);
      background: color-mix(in srgb, var(--is-bg-soft) 80%, transparent);
      color: var(--is-text);
      font: inherit;
      font-size: 0.72rem;
      font-weight: 700;
      cursor: pointer;
      transition: background 160ms ease, border-color 160ms ease, transform 160ms ease;
    }

    .home-cdn__copy:hover {
      background: color-mix(in srgb, var(--hue-a) 16%, var(--is-bg));
      border-color: color-mix(in srgb, var(--hue-a) 45%, transparent);
      transform: translateY(-1px);
    }

    .home-cdn__copy[aria-pressed="true"] {
      background: color-mix(in srgb, var(--is-color-success, #40c057) 22%, transparent);
      border-color: color-mix(in srgb, var(--is-color-success, #40c057) 60%, transparent);
      color: var(--is-color-success, #40c057);
    }

    .home-cdn__actions { display: inline-flex; flex-wrap: wrap; gap: 0.35rem; }

    .home-cdn__pre {
      position: relative;
      margin: 0;
      padding: 0.7rem 0.8rem;
      background: color-mix(in srgb, var(--is-code-bg, #0f1318) 92%, transparent);
      border: 1px solid var(--is-code-border, #1f262e);
      border-radius: 0.55rem;
      font-family: var(--is-mono, ui-monospace, Consolas, monospace);
      font-size: 0.78rem;
      line-height: 1.55;
      color: var(--is-code-text, #d4d8de);
      white-space: pre;
      /* min-width:0 + max-width evitan que el código largo estire la
         columna del hero y se meta debajo del showcase. */
      min-width: 0;
      max-width: 100%;
      box-sizing: border-box;
      overflow-x: auto;
      tab-size: 2;
    }

    .home-cdn__pre[data-lang]::before {
      content: attr(data-lang);
      display: block;
      font-size: 0.62rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--is-text-soft);
      margin-bottom: 0.35rem;
      opacity: 0.65;
    }

    .home-cdn__panel[hidden] { display: none; }

    /* Payoff: los componentes reales renderizados debajo del código. */
    .home-cdn__result {
      display: grid;
      gap: 0.5rem;
      padding: 0.7rem 0.95rem 0.85rem;
      border-top: 1px dashed color-mix(in srgb, var(--hue-a) 35%, var(--hairline));
      background: color-mix(in srgb, var(--is-bg) 40%, transparent);
    }

    .home-cdn__result-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      width: max-content;
      font-size: 0.62rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: color-mix(in srgb, var(--hue-a) 65%, var(--is-text));
    }

    .home-cdn__result-tag::before {
      content: "";
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--is-color-success, #28c840);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--is-color-success, #28c840) 25%, transparent);
    }

    .home-cdn__result-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.85rem;
    }

    /* ═══════════════ STAGE (showcase 3D) ════════════════════════════ */

    .home-stage {
      position: relative;
      perspective: 1600px;
      perspective-origin: 60% 45%;
    }

    .home-stage__grid {
      position: relative;
      display: grid;
      grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
      gap: 1rem;
      transform-style: preserve-3d;
    }

    .home-stage__grid::before {
      content: "";
      position: absolute;
      /* Caja generosa para que la elipse se apague antes del borde: si no,
         el blur deja un canto recto visible sobre el fondo. */
      inset: -38% -30%;
      z-index: -1;
      pointer-events: none;
      background:
        radial-gradient(closest-side, color-mix(in srgb, var(--hue-a) 26%, transparent), transparent 78%) 22% 26% / 70% 70% no-repeat,
        radial-gradient(closest-side, color-mix(in srgb, var(--hue-d) 24%, transparent), transparent 78%) 76% 72% / 66% 66% no-repeat;
      filter: blur(48px);
    }

    .home-col {
      display: flex;
      flex-direction: column;
      gap: 1rem;
      min-width: 0;
      transform-style: preserve-3d;
    }

    .home-col--b { margin-top: 2rem; }

    .tile {
      position: relative;
      background: var(--glass);
      border: 1px solid var(--hairline);
      border-radius: 0.95rem;
      box-shadow: var(--shadow-lift);
      padding: 0.9rem 1rem;
      min-width: 0;
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      transform-style: preserve-3d;
      transition: transform 420ms cubic-bezier(.2,.7,.3,1), box-shadow 420ms ease;
      overflow: hidden;
    }

    /* Cada tile hereda un hue distinto → la fila entera se ve colorida */
    .home-col > .tile:nth-child(1) { --tile-hue: var(--hue-a); }
    .home-col > .tile:nth-child(2) { --tile-hue: var(--hue-b); }
    .home-col > .tile:nth-child(3) { --tile-hue: var(--hue-d); }
    .home-col--b > .tile:nth-child(1) { --tile-hue: var(--hue-c); }
    .home-col--b > .tile:nth-child(2) { --tile-hue: var(--hue-e); }
    .home-col--b > .tile:nth-child(3) { --tile-hue: var(--hue-b); }

    /* Filo superior de color: firma visual barata y limpia */
    .tile::before {
      content: "";
      position: absolute;
      inset: 0 0 auto;
      height: 2px;
      background: linear-gradient(90deg,
        transparent,
        color-mix(in srgb, var(--tile-hue, var(--hue-a)) 85%, transparent),
        transparent);
      opacity: 0.9;
      pointer-events: none;
    }

    .tile::after {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: radial-gradient(120% 70% at 50% 0%,
        color-mix(in srgb, var(--tile-hue, var(--hue-a)) 16%, transparent), transparent 62%);
      opacity: 0.5;
      transition: opacity 420ms ease;
    }

    .tile:hover {
      transform: translateZ(28px) rotateY(2.5deg) rotateX(-1.5deg);
      box-shadow: var(--shadow-pop);
    }

    .tile:hover::after { opacity: 0.9; }

    .tile > * { position: relative; z-index: 1; }

    .tile--accent {
      background: linear-gradient(135deg,
        color-mix(in srgb, var(--hue-a) 92%, #000),
        color-mix(in srgb, var(--hue-b) 80%, #000));
      border-color: transparent;
      color: #fff;
    }

    .tile--accent .tile__muted { color: rgb(255 255 255 / 78%); }
    .tile--accent .tile__title { color: #fff; }

    .tile__eyebrow {
      margin: 0 0 0.35rem;
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: color-mix(in srgb, var(--tile-hue, var(--hue-a)) 70%, var(--is-text-soft));
    }

    .tile__title {
      margin: 0;
      font-size: 0.95rem;
      font-weight: 700;
      line-height: 1.35;
      color: var(--is-text);
    }

    .tile__muted { margin: 0.35rem 0 0; font-size: 0.78rem; color: var(--is-text-soft); }

    /* Charts dentro de tile: alto explícito → sin colapsos ni solapes */
    .tile is-bar-chart,
    .tile is-line-chart,
    .tile is-doughnut-chart,
    .tile is-radar-chart,
    .tile is-polar-area-chart {
      display: block;
      width: 100%;
      margin-top: 0.5rem;
    }

    .tile--chart-bar   is-bar-chart        { height: 9rem; }
    .tile--chart-line  is-line-chart       { height: 8rem; }
    .tile--chart-donut is-doughnut-chart   { height: 10rem; }
    .tile--chart-radar is-radar-chart      { height: 10rem; }
    .tile--chart-polar is-polar-area-chart { height: 10rem; }

    .tile__row { display: flex; align-items: center; gap: 0.55rem; margin-top: 0.75rem; }
    .tile__chips { display: flex; flex-wrap: wrap; gap: 0.4rem; }

    .kpi {
      display: grid;
      grid-template-columns: 1fr auto;
      align-items: end;
      gap: 0.65rem;
    }

    .kpi__value {
      font-size: 1.85rem;
      font-weight: 800;
      letter-spacing: -0.025em;
      line-height: 1;
      /* Métrica en color sólido: la cifra debe leerse, no decorar. */
      color: var(--is-text);
    }

    .kpi__delta {
      margin-top: 0.2rem;
      font-size: 0.78rem;
      font-weight: 700;
      color: var(--is-color-success, #40c057);
    }

    .kpi__spark { grid-column: 1 / -1; height: 2.4rem; margin-top: 0.4rem; }

    .tile__list {
      margin: 0;
      padding: 0;
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.55rem;
    }

    .tile__list li {
      display: flex;
      align-items: flex-start;
      gap: 0.5rem;
      font-size: 0.82rem;
      color: var(--is-text);
      line-height: 1.35;
    }

    .tile__list is-icon {
      flex-shrink: 0;
      margin-top: 0.1rem;
      color: color-mix(in srgb, var(--tile-hue, var(--hue-a)) 80%, var(--is-text));
    }

    .tile__msg { display: flex; align-items: center; gap: 0.65rem; }
    .tile__msg-body { flex: 1; min-width: 0; }
    .tile__msg-body strong { display: block; font-size: 0.82rem; }
    .tile__msg-body span { font-size: 0.72rem; color: var(--is-text-soft); }

    /* ═══════════════ ENCABEZADOS DE SECCIÓN ═════════════════════════ */

    .home-lab__head {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 0.85rem;
      margin-bottom: 1.35rem;
    }

    .home-lab__title {
      margin: 0 0 0.4rem;
      font-size: clamp(1.5rem, 2.6vw, 2.25rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      color: var(--is-text);
    }

    .home-lab__title em {
      font-style: normal;
      background: linear-gradient(115deg, var(--hue-a), var(--hue-b) 45%, var(--hue-d));
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
      color: transparent;
      /* Mismo motivo que .home-title__accent: con relleno transparente la
         text-shadow heredada se ve a traves del glifo y lo despinta. */
      text-shadow: none;
    }

    /* Mismo problema que el acento del hero: los hues crudos se calibraron
       para fondo oscuro. Sobre el blanco del tema light, agrowin cae a 1.9:1
       (ilegible) y contapyme a 4.2:1. Fallback plano primero —si el color
       relativo no se soporta, la declaracion entera se descarta y el texto
       queda transparente— y tope ABSOLUTO de luminosidad dentro de @supports. */
    [data-theme="light"] .home-lab__title em {
      background: none;
      color: var(--is-color-brand-stronger, #a61e1e);
      -webkit-text-fill-color: currentColor;
    }

    @supports (color: oklch(from red min(l, 0.5) c h)) {
      [data-theme="light"] .home-lab__title em {
        background: linear-gradient(115deg,
          oklch(from var(--hue-a) min(l, 0.50) c h),
          oklch(from var(--hue-b) min(l, 0.48) c h) 45%,
          oklch(from var(--hue-d) min(l, 0.46) c h));
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
      }
    }

    .home-lab__lede {
      margin: 0;
      max-width: 40rem;
      font-size: 0.94rem;
      color: var(--is-text-soft);
      line-height: 1.55;
    }

    .home-lab__chips { display: flex; flex-wrap: wrap; gap: 0.4rem; align-items: center; }
    .home-lab__chips is-tag { font-size: 0.72rem; }

    /* Subtítulo del segundo bloque dentro de la misma sección */
    .home-lab__subhead {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      gap: 0.6rem;
      margin: clamp(2rem, 4vw, 3rem) 0 1.1rem;
      padding-bottom: 0.55rem;
      border-bottom: 1px solid var(--hairline);
      font-size: 1.05rem;
      font-weight: 700;
      letter-spacing: -0.01em;
      color: var(--is-text);
    }

    .home-lab__subhead span { position: relative; padding-left: 0.7rem; }

    .home-lab__subhead span::before {
      content: "";
      position: absolute;
      left: 0;
      top: 0.12em;
      bottom: 0.12em;
      width: 3px;
      border-radius: 2px;
      background: linear-gradient(180deg, var(--hue-a), var(--hue-d));
    }

    .home-lab__subhead small {
      font-size: 0.78rem;
      font-weight: 500;
      color: var(--is-text-soft);
    }

    /* ═══════════════ SHOWCASE (collage + charts lab) ════════════════
       Una sola sección: grid determinista de 6 columnas (charts span 2,
       diagramas span 3 → 24 celdas = 4 filas exactas). Nada se solapa. */

    .home-showcase {
      position: relative;
      padding: clamp(1rem, 3vw, 2rem) 0 0;
      perspective: 1800px;
      perspective-origin: 50% 40%;
      isolation: isolate;
    }

    .home-showcase::before {
      content: "";
      position: absolute;
      inset: 4% -6% 0;
      z-index: -1;
      pointer-events: none;
      background:
        radial-gradient(55% 40% at 22% 28%, color-mix(in srgb, var(--hue-b) 24%, transparent), transparent 64%),
        radial-gradient(50% 38% at 82% 68%, color-mix(in srgb, var(--hue-c) 22%, transparent), transparent 66%);
      filter: blur(56px);
    }

    .home-collage__track {
      display: grid;
      /* 6 columnas: charts span 2, diagramas span 3 → 9×2 + 2×3 = 24 = 4
         filas exactas de 6. Rejilla llena sin huecos ni spans irregulares. */
      grid-template-columns: repeat(6, minmax(0, 1fr));
      grid-auto-rows: 16.5rem;
      grid-auto-flow: dense;
      gap: 1.15rem;
      transform-style: preserve-3d;
    }

    .collage-card {
      position: relative;
      display: grid;
      grid-template-rows: auto minmax(0, 1fr) auto;
      gap: 0.5rem;
      padding: 0.9rem 1rem 0.95rem;
      min-width: 0;
      background: linear-gradient(180deg,
        color-mix(in srgb, var(--is-bg-elev) 94%, transparent),
        color-mix(in srgb, var(--is-bg-elev) 80%, transparent));
      border: 1px solid var(--hairline);
      border-radius: 1rem;
      box-shadow: var(--shadow-lift);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      overflow: hidden;
      isolation: isolate;
      transform-style: preserve-3d;
      /* El parallax JS escribe estas vars; el hover suma su propio lift
         sin pisar el transform (antes iba inline y mataba el :hover). */
      --px: 0px; --py: 0px; --pz: 0px; --pry: 0deg; --prx: 0deg;
      --lift: 0px;
      --tilt-y: 0deg;
      --tilt-x: 0deg;
      transform:
        translate3d(var(--px), var(--py), calc(var(--pz) + var(--lift)))
        rotateY(calc(var(--pry) + var(--tilt-y)))
        rotateX(calc(var(--prx) + var(--tilt-x)));
      transition: transform 480ms cubic-bezier(.2,.7,.3,1), box-shadow 480ms ease;
    }

    /* Rotación de hues por posición: collage colorido pero coherente */
    .collage-card:nth-child(6n+1) { --card-hue: var(--hue-a); }
    .collage-card:nth-child(6n+2) { --card-hue: var(--hue-b); }
    .collage-card:nth-child(6n+3) { --card-hue: var(--hue-d); }
    .collage-card:nth-child(6n+4) { --card-hue: var(--hue-c); }
    .collage-card:nth-child(6n+5) { --card-hue: var(--hue-e); }
    .collage-card:nth-child(6n)   { --card-hue: var(--hue-b); }

    .collage-card::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: 0;
      border-radius: inherit;
      padding: 1px;
      background: linear-gradient(135deg,
        color-mix(in srgb, var(--card-hue, var(--hue-a)) 70%, transparent),
        transparent 45%,
        color-mix(in srgb, var(--card-hue, var(--hue-a)) 40%, transparent));
      mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      mask-composite: exclude;
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask-composite: xor;
      opacity: 0.7;
      pointer-events: none;
    }

    .collage-card::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: 0;
      border-radius: inherit;
      background: radial-gradient(130% 80% at 50% 0%,
        color-mix(in srgb, var(--card-hue, var(--hue-a)) 20%, transparent), transparent 62%);
      opacity: 0.45;
      pointer-events: none;
      transition: opacity 480ms ease;
    }

    .collage-card:hover {
      --lift: 40px;
      --tilt-y: 2deg;
      --tilt-x: -1.5deg;
      box-shadow: var(--shadow-pop);
      z-index: 4;
    }

    .collage-card:hover::after { opacity: 0.85; }

    /* Botón "abrir demo": lo inyecta JS en cada card que tenga un is-*
       compatible. Top-right, sutil por defecto, opaco al hover. */
    .card-demo {
      position: absolute;
      top: 0.5rem;
      right: 0.5rem;
      z-index: 3;
      appearance: none;
      width: 1.7rem;
      height: 1.7rem;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 0;
      border-radius: 999px;
      border: 1px solid var(--hairline);
      background: var(--glass-strong);
      color: var(--is-text-soft);
      cursor: pointer;
      opacity: 0.55;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
      transition: opacity 220ms ease, color 200ms ease, border-color 200ms ease,
                  background 200ms ease, transform 220ms cubic-bezier(.2,.7,.3,1);
    }
    .card-demo:hover,
    .card-demo:focus-visible {
      opacity: 1;
      color: var(--is-text);
      border-color: color-mix(in srgb, var(--card-hue, var(--hue-a)) 60%, transparent);
      background: color-mix(in srgb, var(--card-hue, var(--hue-a)) 14%, var(--glass-strong));
      transform: translateY(-1px);
      outline: none;
    }
    .card-demo is-icon {
      width: 0.9rem;
      height: 0.9rem;
      pointer-events: none;
    }

    .collage-card__title {
      margin: 0;
      position: relative;
      z-index: 1;
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.07em;
      text-transform: uppercase;
      color: color-mix(in srgb, var(--card-hue, var(--hue-a)) 62%, var(--is-text-soft));
    }

    .collage-card__plot {
      position: relative;
      z-index: 1;
      min-height: 0;
      min-width: 0;
      display: grid;
      place-items: stretch;
      contain: layout paint;
    }

    .collage-card__meta {
      position: relative;
      z-index: 1;
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.5rem;
      font-size: 0.7rem;
      color: var(--is-text-soft);
      padding-top: 0.3rem;
      border-top: 1px solid color-mix(in srgb, var(--is-border) 45%, transparent);
    }

    .collage-card__meta b {
      color: var(--is-text);
      font-variant-numeric: tabular-nums;
      font-weight: 700;
    }

    /* Filas uniformes de 15rem: 11 cards + 1 doble = 12 celdas = 3×4 exactas.
       Los spans variables (masonry) dejaban huecos y desalineaban las filas;
       el ritmo lo dan la profundidad y el hue, no el tamaño. */
    .collage-card--s,
    .collage-card--m,
    .collage-card--l,
    .collage-card--tall { grid-row: span 1; grid-column: span 2; }
    .collage-card--xl   { grid-row: span 1; grid-column: span 3; }

    /* Un único bloque para todos los charts del collage: llenan el plot */
    .collage-card__plot > * {
      display: block;
      width: 100%;
      height: 100%;
      min-width: 0;
      min-height: 0;
    }

    /* ── Cintas: bandas horizontales EN EL FLUJO, al nivel de las cards
       (antes eran barras verticales absolutas con z-index 5 que pasaban
       por delante de los charts). ─────────────────────────────────── */
    .collage-ribbons {
      display: grid;
      gap: 0.55rem;
      margin: 1.4rem 0;
      perspective: 900px;
      perspective-origin: 50% 50%;
      transform-style: preserve-3d;
      pointer-events: none;
      overflow: hidden;
      mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent);
    }

    .collage-ribbon {
      position: relative;
      display: flex;
      align-items: center;
      overflow: hidden;
      padding: 0.42rem 0;
      border-radius: 0.6rem;
      background: linear-gradient(90deg,
        color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 10%, var(--glass)),
        color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 4%, var(--glass)));
      border-top: 1px solid color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 42%, transparent);
      border-bottom: 1px solid color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 22%, transparent);
      box-shadow:
        0 1px 0 color-mix(in srgb, #fff 7%, transparent) inset,
        0 14px 30px rgb(0 0 0 / 22%);
      color: var(--is-text);
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
      transform-style: preserve-3d;
      will-change: transform;
    }

    /* Cada cinta con su propia inclinación 3D → tejido en profundidad */
    .collage-ribbon--c1 { --ribbon-hue: var(--hue-a); transform: rotateX(11deg)  translateZ(-14px); }
    .collage-ribbon--c2 { --ribbon-hue: var(--hue-b); transform: rotateX(-9deg)  translateZ(10px); }
    .collage-ribbon--c3 { --ribbon-hue: var(--hue-d); transform: rotateX(9deg)   translateZ(-10px); }
    .collage-ribbon--c4 { --ribbon-hue: var(--hue-c); transform: rotateX(-11deg) translateZ(12px); }

    .collage-ribbon__track {
      display: inline-flex;
      align-items: center;
      gap: 0.9rem;
      flex: none;
      padding-right: 0.9rem;
      white-space: nowrap;
      will-change: transform;
    }

    /* El contenido está duplicado en el HTML → -50% es un bucle perfecto */
    .collage-ribbon--c1 .collage-ribbon__track { animation: ribbon-slide 34s linear infinite; }
    .collage-ribbon--c2 .collage-ribbon__track { animation: ribbon-slide 28s linear infinite reverse; }
    .collage-ribbon--c3 .collage-ribbon__track { animation: ribbon-slide 31s linear infinite; }
    .collage-ribbon--c4 .collage-ribbon__track { animation: ribbon-slide 25s linear infinite reverse; }

    @keyframes ribbon-slide {
      from { transform: translateX(0); }
      to   { transform: translateX(-50%); }
    }

    .collage-ribbon__item {
      display: inline-flex;
      align-items: center;
      gap: 0.3rem;
      padding: 0.12rem 0.6rem;
      border-radius: 999px;
      background: color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 18%, transparent);
      border: 1px solid color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 38%, transparent);
      color: var(--is-text);
    }

    .collage-ribbon__dot {
      color: color-mix(in srgb, var(--ribbon-hue, var(--hue-a)) 85%, transparent);
      font-size: 0.6rem;
      opacity: 0.9;
    }

    /* ── Segundo bloque: grid de charts (misma sección) ─────────────── */

    .home-lab__grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(19rem, 1fr));
      gap: 1.15rem;
      transform-style: preserve-3d;
    }

    .lab-card {
      position: relative;
      display: grid;
      grid-template-rows: auto 1fr;
      gap: 0.5rem;
      padding: 0.95rem 1rem 1rem;
      background: var(--glass);
      border: 1px solid var(--hairline);
      border-radius: 0.95rem;
      box-shadow: var(--shadow-lift);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      transform-style: preserve-3d;
      transition: transform 420ms cubic-bezier(.2,.7,.3,1), box-shadow 420ms ease;
      min-width: 0;
      overflow: hidden;
    }

    .lab-card:nth-child(5n+1) { --card-hue: var(--hue-a); }
    .lab-card:nth-child(5n+2) { --card-hue: var(--hue-b); }
    .lab-card:nth-child(5n+3) { --card-hue: var(--hue-d); }
    .lab-card:nth-child(5n+4) { --card-hue: var(--hue-c); }
    .lab-card:nth-child(5n)   { --card-hue: var(--hue-e); }

    .lab-card::before {
      content: "";
      position: absolute;
      inset: 0 0 auto;
      height: 2px;
      background: linear-gradient(90deg,
        transparent,
        color-mix(in srgb, var(--card-hue, var(--hue-a)) 85%, transparent),
        transparent);
      pointer-events: none;
    }

    .lab-card:hover {
      transform: translateZ(26px) rotateY(2deg) rotateX(-1.2deg);
      box-shadow: var(--shadow-pop);
      z-index: 2;
    }

    .lab-card__title {
      margin: 0;
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.07em;
      text-transform: uppercase;
      color: color-mix(in srgb, var(--card-hue, var(--hue-a)) 62%, var(--is-text-soft));
    }

    .lab-card__plot { min-height: 11rem; min-width: 0; }

    .lab-card__plot > is-bar-chart,
    .lab-card__plot > is-line-chart,
    .lab-card__plot > is-pie-chart,
    .lab-card__plot > is-doughnut-chart,
    .lab-card__plot > is-polar-area-chart,
    .lab-card__plot > is-radar-chart,
    .lab-card__plot > is-scatter-chart,
    .lab-card__plot > is-bubble-chart {
      display: block;
      width: 100%;
      height: 11rem;
    }

    .lab-card__plot--tall .lab-card__plot > is-radar-chart { height: 13rem; }

    .lab-card__sparklines { display: grid; gap: 0.5rem; padding-top: 0.4rem; }

    .lab-card__sparklines .row {
      display: grid;
      grid-template-columns: 1fr auto auto;
      align-items: center;
      gap: 0.65rem;
      padding: 0.32rem 0;
      border-bottom: 1px dashed color-mix(in srgb, var(--is-border) 55%, transparent);
      font-size: 0.85rem;
    }

    .lab-card__sparklines .row:last-child { border-bottom: 0; }
    .lab-card__sparklines .row b { font-variant-numeric: tabular-nums; }
    .lab-card__sparklines is-sparkline { width: 6rem; }

    /* ═══════════════ RESPONSIVE ═════════════════════════════════════ */

    @media (max-width: 1240px) {
      .home-collage__track { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    }

    @media (max-width: 960px) {
      .home {
        grid-template-columns: minmax(0, 1fr);
        grid-template-areas:
          "hero"
          "stage"
          "showcase";
        align-items: start;
      }
      .home-hero { max-width: none; }
      .home-col--b { margin-top: 0; }
      .home-collage__track { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .collage-card--s,
      .collage-card--m,
      .collage-card--l,
      .collage-card--tall { grid-column: span 1; }
      .collage-card--xl { grid-column: span 2; }
    }

    @media (max-width: 620px) {
      .home-collage__track {
        grid-template-columns: minmax(0, 1fr);
        grid-auto-rows: 14rem;
      }
      .collage-card--s,
      .collage-card--m,
      .collage-card--l,
      .collage-card--xl,
      .collage-card--tall { grid-column: span 1; grid-row: span 1; }
      .home-stage__grid { grid-template-columns: minmax(0, 1fr); }
      .collage-ribbon--c3,
      .collage-ribbon--c4 { display: none; }
    }

    /* ═══════════════ SCROLL-DRIVEN REVEALS ══════════════════════════
       Los tiles, lab-cards y secciones entran ligados a la posición de
       scroll (animation-timeline: view()): aparecen, suben y se
       desvanecen conforme cruzan el viewport del is-main scrolleable.
       Solo donde el navegador lo soporta; reduced-motion lo apaga. */
    @supports (animation-timeline: view()) {
      @media (prefers-reduced-motion: no-preference) {
        .tile,
        .lab-card,
        .home-lab__head,
        .home-showcase .collage-card {
          animation: home-rise-in linear both;
          animation-timeline: view();
          animation-range: entry 0% entry 65%;
        }
        /* Al salir por arriba se atenúan, para que el foco siga al scroll. */
        .tile,
        .lab-card {
          animation-name: home-rise-in, home-fade-out;
          animation-timeline: view(), view();
          animation-range: entry 0% entry 65%, exit 40% exit 100%;
        }
        /* El hero se despide: se desliza y desvanece suave al scrollear. */
        .home-hero {
          animation: home-hero-out linear both;
          animation-timeline: view();
          animation-range: exit 0% exit 90%;
        }
      }
    }

    @keyframes home-hero-out {
      to { opacity: 0.15; transform: translateY(-28px) scale(0.99); }
    }

    /* Barra de progreso de lectura, fija sobre el scroller. Usa los tokens
       propios de is-progress-bar (--track-height / --track-color /
       --indicator-color); el track transparente la deja como un hilo. */
    .home-progress {
      position: sticky;
      top: 0;
      z-index: 20;
      --track-height: 3px;
      --track-color: transparent;
      --indicator-color: linear-gradient(90deg, var(--hue-a), var(--hue-b));
      pointer-events: none;
    }
    /* El indicador trae transition de 200ms: en scroll se ve retrasado. */
    .home-progress::part(indicator) { transition: none; }

    /* Fallback de reveal para navegadores sin animation-timeline: view().
       El estado inicial solo se aplica si el JS marcó .is-reveal, así que
       sin JS el contenido queda visible (no se pierde nada). */
    .is-reveal {
      opacity: 0;
      transform: translateY(26px) scale(0.985);
      transition: opacity 520ms cubic-bezier(0.22, 1, 0.36, 1),
                  transform 520ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .is-reveal.is-revealed {
      opacity: 1;
      transform: none;
    }

    @keyframes home-rise-in {
      from { opacity: 0; transform: translateY(26px) scale(0.985); }
      to { opacity: 1; transform: none; }
    }

    @keyframes home-fade-out {
      from { opacity: 1; }
      to { opacity: 0.25; }
    }

    @media (prefers-reduced-motion: reduce) {
      is-main.home-main::before,
      .home-hero::before,
      .home-hero::after,
      .home-kicker::before,
      .tile,
      .lab-card,
      .home-lab__head,
      .collage-ribbon__track { animation: none !important; }

      .home-hero:hover .home-title,
      .home-hero:hover .home-actions,
      .tile:hover,
      .lab-card:hover { transform: none !important; }

      .collage-card { transform: none !important; transition: box-shadow 200ms ease; }
    }

    /* ═══════════════ LIGHT MODE ═════════════════════════════════════
       El diseño base asume dark mode: shadows negras fuertes, halos
       con hues oscuros, gradientes que en light mode quedan demasiado
       pesados. Aquí se suavizan sombras, se baja la opacidad de los
       halos aurora y se refuerza el highlight blanco (que en dark era
       casi invisible y en light ayuda a definir los cantos). */
    [data-theme="light"] .home {
      --shadow-lift:
        0 1px 0 color-mix(in srgb, #fff 75%, transparent) inset,
        0 10px 24px rgb(0 0 0 / 9%),
        0 2px 6px rgb(0 0 0 / 5%);
      --shadow-pop:
        0 1px 0 color-mix(in srgb, #fff 92%, transparent) inset,
        0 20px 44px rgb(0 0 0 / 13%),
        0 4px 12px rgb(0 0 0 / 7%);
    }

    [data-theme="light"] .home-title {
      text-shadow:
        0 1px 0 color-mix(in srgb, #fff 70%, transparent),
        0 2px 6px rgb(0 0 0 / 7%),
        0 16px 32px rgb(0 0 0 / 10%);
    }

    /* El degradado del acento está calibrado para fondo oscuro: su parada
       central es `color-mix(--hue-d 78%, #fff)`, o sea un pastel, y --hue-d
       nace ya aclarado (l * 1.02). Sobre el #fff del tema light eso es texto
       casi invisible.

       El tope es ABSOLUTO (`min(l, …)`), no un porcentaje: las semillas de las
       paletas parten de luminosidades muy distintas (insoft #e03131 → L .59;
       agrowin yellowgreen → L .79), así que un `calc(l * 0.78)` uniforme deja
       agrowin en 3.5:1 mientras hunde insoft. Con el tope, el peor caso de las
       tres paletas es 7.62:1 sobre blanco (contapyme, parada --hue-c); el
       fallback plano baja a 4.15:1 (agrowin), que sigue por encima del 3:1 de
       AA para texto grande. Matiz y croma de marca se conservan. */
    [data-theme="light"] .home-title__accent {
      /* Fallback SIN color relativo ni min(): si el navegador no soporta
         alguna de las dos cosas, la declaracion de abajo se descarta entera y
         volveriamos al degradado claro (texto invisible). Este color plano es
         el peor caso aceptable, no un adorno. */
      background: none;
      color: var(--is-color-brand-stronger, #a61e1e);
      -webkit-text-fill-color: currentColor;
    }

    @supports (color: oklch(from red min(l, 0.5) c h)) {
      [data-theme="light"] .home-title__accent {
        background: linear-gradient(115deg,
          oklch(from var(--hue-a) min(l, 0.42) c h) 0%,
          oklch(from var(--hue-b) min(l, 0.40) c h) 26%,
          oklch(from var(--hue-d) min(l, 0.38) c h) 52%,
          oklch(from var(--hue-c) min(l, 0.40) c h) 76%,
          oklch(from var(--hue-a) min(l, 0.42) c h) 100%);
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
      }
    }

    [data-theme="light"] is-main.home-main::before {
      opacity: 0.32;
    }

    [data-theme="light"] .home-hero::before {
      opacity: 0.28;
    }

    [data-theme="light"] .home-hero::after {
      opacity: 0.55;
    }

    [data-theme="light"] .home-stage__grid::before,
    [data-theme="light"] .home-showcase::before {
      opacity: 0.5;
    }

    [data-theme="light"] .home-cdn {
      box-shadow: 0 14px 34px rgb(0 0 0 / 12%), 0 2px 8px rgb(0 0 0 / 7%);
    }

    [data-theme="light"] .home-kicker {
      box-shadow:
        0 1px 0 color-mix(in srgb, #fff 75%, transparent) inset,
        0 4px 14px color-mix(in srgb, var(--hue-a) 14%, transparent);
    }

    [data-theme="light"] .home-actions #ctaExplore {
      box-shadow:
        0 6px 18px color-mix(in srgb, var(--hue-a) 22%, transparent),
        0 2px 4px color-mix(in srgb, var(--hue-a) 14%, transparent);
    }

    [data-theme="light"] .home-cdn__tab[aria-pressed="true"] {
      box-shadow: 0 4px 12px color-mix(in srgb, var(--hue-a) 22%, transparent);
    }

    [data-theme="light"] .collage-ribbon {
      box-shadow:
        0 1px 0 color-mix(in srgb, #fff 60%, transparent) inset,
        0 8px 18px rgb(0 0 0 / 10%);
    }

    [data-theme="light"] .tile::after,
    [data-theme="light"] .collage-card::after {
      opacity: 0.25;
    }
